        #region Is AutoGenerated Serial No
        public static bool IsAutoGenerated(string sConfigFormID)
        {
            bool bAuto = false;
            tbl_securityConfigForms detail = tbl_securityConfigForms.Select(sConfigFormID);
            if (detail != null)
                bAuto = detail.IsAutoGenerate;

            return bAuto;
        }

        public static bool IsAutoGenerated_Advanced(string sConfigFormID, string sSalesNote_ID, ref System.Windows.Forms.TextBox txt,bool bIsUpdate)
        {
            enum_SerialType ST = enum_SerialType.Standerd;
            bool bStatus= IsAutoGenerated_Advanced(sConfigFormID, sSalesNote_ID, ref txt, ref ST, bIsUpdate,false);
            return bStatus;
        }

        public static bool IsAutoGenerated_Advanced(string sConfigFormID, string sSalesNote_ID, ref System.Windows.Forms.TextBox txt, ref enum_SerialType ST, bool bIsUpdate,bool bCheckOnly)
        {
            bool bAuto = false;
            ST = enum_SerialType.Standerd;

            if (!bIsUpdate)
            {
                tbl_securityConfigForms detail = tbl_securityConfigForms.Select(sConfigFormID);
                if (detail != null && detail.IsAutoGenerate)
                {
                    ST = (enum_SerialType)detail.SerialType;

                    if (ST == enum_SerialType.BranchWice)
                    {
                        tbl_securityConfigForms_Advanced oAdv = tbl_securityConfigForms_Advanced.Select(clsSecurity.CompanyID, clsSecurity.BranchID, sConfigFormID, "default");
                        if (oAdv != null && oAdv.IsAutoGenerate)
                            bAuto = oAdv.IsAutoGenerate;
                    }
                    else if (ST == enum_SerialType.NoteType)
                    {
                        tbl_securityConfigForms_Advanced oAdv = tbl_securityConfigForms_Advanced.Select(clsSecurity.CompanyID, "default", sConfigFormID, sSalesNote_ID);
                        if (oAdv != null && oAdv.IsAutoGenerate)
                            bAuto = true;
                    }
                    else if (ST == enum_SerialType.BranchWise_NoteType)
                    {
                        tbl_securityConfigForms_Advanced oAdv = tbl_securityConfigForms_Advanced.Select(clsSecurity.CompanyID, clsSecurity.BranchID, sConfigFormID, sSalesNote_ID);
                        if (oAdv != null && oAdv.IsAutoGenerate)
                            bAuto = true;
                    }
                    else
                        bAuto = detail.IsAutoGenerate;
                }
                if (!bCheckOnly)
                {
                    if (bAuto)
                        txt.Text = "<Auto Generate>";
                    else
                        txt.Clear();
                }
            }
            return bAuto;
        }
        #endregion

        #region Get Auto Generated Code
        public static string getAutoGeneratedCode_Advanced(string sConfigFormID, string sSalesNote_ID, ref System.Windows.Forms.TextBox txt)
        {
            string sCode = "";
            tbl_securityConfigForms detail = tbl_securityConfigForms.Select(sConfigFormID);
            if (detail != null && detail.IsAutoGenerate)
            {
                enum_SerialType ST = (enum_SerialType)detail.SerialType;
                if (ST == enum_SerialType.BranchWice)
                {
                    #region Branch Wice
                    tbl_securityConfigForms_Advanced oAdv = tbl_securityConfigForms_Advanced.Select(clsSecurity.CompanyID, clsSecurity.BranchID, sConfigFormID, "default");
                    if (oAdv != null && oAdv.IsAutoGenerate)
                    {
                        sCode += oAdv.Prefix;
                        sCode += oAdv.Counter.ToString(getWidthFormat(oAdv.Length));
                        oAdv.Counter++;
                        oAdv.Update();
                    }
                    #endregion
                }
                else if (ST == enum_SerialType.NoteType)
                {
                    #region Sales Note Type
                    tbl_securityConfigForms_Advanced oAdv = tbl_securityConfigForms_Advanced.Select(clsSecurity.CompanyID, "default", sConfigFormID, sSalesNote_ID);
                    if (oAdv != null && oAdv.IsAutoGenerate)
                    {
                        sCode += oAdv.Prefix;
                        sCode += oAdv.Counter.ToString(getWidthFormat(oAdv.Length));
                        oAdv.Counter++;
                        oAdv.Update();
                    }
                    #endregion
                }
                else if (ST == enum_SerialType.BranchWise_NoteType)
                {
                    #region Branch Wice Sales Note Type
                    tbl_securityConfigForms_Advanced oAdv = tbl_securityConfigForms_Advanced.Select(clsSecurity.CompanyID, clsSecurity.BranchID, sConfigFormID, sSalesNote_ID);
                    if (oAdv != null && oAdv.IsAutoGenerate)
                    {
                        sCode += oAdv.Prefix;
                        sCode += oAdv.Counter.ToString(getWidthFormat(oAdv.Length));
                        oAdv.Counter++;
                        oAdv.Update();
                    }
                    #endregion
                }
                else
                {
                    #region Standerd
                    if (detail.Prefix1 != null && detail.Prefix1.Length > 0)
                    {
                        sCode += detail.Prefix1;
                        if (detail.Seperator1 != null && detail.Seperator1.Length > 0)
                        {
                            sCode += detail.Seperator1;
                            if (detail.Prefix2 != null && detail.Prefix2.Length > 0)
                            {
                                sCode += detail.Prefix2;
                                if (detail.Seperator2 != null && detail.Seperator2.Length > 0)
                                    sCode += detail.Seperator2;

                            }
                        }
                    }
                    sCode += detail.Counter.ToString(getWidthFormat(detail.Length));
                    detail.Counter++;
                    detail.Update();
                    #endregion
                }
            }

            if (sCode != "")
                txt.Text = sCode;

            return sCode;
        }

