        public static string getAutoGeneratedCode(string sConfigFormID)
        {
            string sCode = "";
            tbl_securityConfigForms detail = tbl_securityConfigForms.Select(sConfigFormID);
            if (detail != null)
            {
                if (detail.Prefix1 != null && detail.Prefix1.Length > 0)
                {
                    sCode += detail.Prefix1;
                    if (detail.Seperator1 != null && detail.Seperator1.Length > 0)
                    {
                        sCode += detail.Seperator1;
                        if (detail.Prefix2 != null && detail.Prefix2.Length > 0)
                        {
                            sCode += detail.Prefix2;
                            if (detail.Seperator2 != null && detail.Seperator2.Length > 0)
                            {
                                sCode += detail.Seperator2;
                            }
                        }
                    }
                }
                sCode += detail.Counter.ToString(getWidthFormat(detail.Length));
                detail.Counter++;
                detail.Update();
            }
            return sCode;
        }

        public static string getAutoGeneratedCode_AccCode(string sConfigFormID, string sGLCode, string sSubGLCode, string sAccType)
        {
            string sCode = "";
            tbl_securityConfigForms detail = tbl_securityConfigForms.Select(sConfigFormID);
            if (detail != null)
            {
                if (detail.Prefix1 != null && detail.Prefix1.Length > 0)
                {
                    sCode += detail.Prefix1;
                    if (detail.Seperator1 != null && detail.Seperator1.Length > 0)
                    {
                        sCode += detail.Seperator1;

                        tbl_zAccGLMaster_AccountType detailAccType = tbl_zAccGLMaster_AccountType.Select(sAccType);
                        if(detailAccType != null)
                        {
                            sCode += sGLCode + "/" + sSubGLCode + "/" + sAccType + "/";

                            sCode += detailAccType.Counter.ToString(getWidthFormat(detail.Length));
                            detailAccType.Counter++;
                            detailAccType.Update();
                        }
                    }
                }
            }
            return sCode;
        }

