        public static string getAutoGeneratedCode_ImportAndExport(string sConfigFormID_Export, string sConfigFormID_Local, string sConfigFormID_Staff, string sCustomerID)
        {
            string sCode = "";
            tbl_securityConfigForms detail = null;
            tbl_genCustomerMaster oCustomer = tbl_genCustomerMaster.Select(sCustomerID);
            if (oCustomer != null && oCustomer.Customer_ID != "default")
            {
                if (oCustomer.CustomerType_ID == "1")//Local
                    detail = tbl_securityConfigForms.Select(sConfigFormID_Local);
                else if (oCustomer.CustomerType_ID == "2")//Export
                    detail = tbl_securityConfigForms.Select(sConfigFormID_Export);
                else if (oCustomer.CustomerType_ID == "3")//Staff
                    detail = tbl_securityConfigForms.Select(sConfigFormID_Staff);
            }
            if (detail != null)
            {
                if (detail.Prefix1 != null && detail.Prefix1.Length > 0)
                {
                    sCode += detail.Prefix1;
                    if (detail.Seperator1 != null && detail.Seperator1.Length > 0)
                    {
                        sCode += detail.Seperator1;
                        if (detail.Prefix2 != null && detail.Prefix2.Length > 0)
                        {
                            sCode += detail.Prefix2;
                            if (detail.Seperator2 != null && detail.Seperator2.Length > 0)
                            {
                                sCode += detail.Seperator2;
                            }
                        }
                    }
                }
                sCode += detail.Counter.ToString(getWidthFormat(detail.Length));
                detail.Counter++;
                detail.Update();
            }
            return sCode;
        }
