        public static string getChequeStatusName(ChequeStatus cStatus)
        {
            return cStatus.ToString().Replace('_', ' ');
        }

        public static string getChequeStatusID(ChequeStatus cStatus)
        {
            string sStatusID = "default";
            switch (cStatus)
            {
                case ChequeStatus.New:
                    sStatusID = "0";
                    break;
                case ChequeStatus.Deposited:
                    sStatusID = "1";
                    break;
                case ChequeStatus.ReIssued:
                    sStatusID = "2";
                    break;
                case ChequeStatus.Realized:
                    sStatusID = "3";
                    break;
                case ChequeStatus.Returned_R:
                    sStatusID = "4";
                    break;
                case ChequeStatus.Returned_NR_C:
                    sStatusID = "5";
                    break;
                case ChequeStatus.Returned_NR_O:
                    sStatusID = "6";
                    break;
                case ChequeStatus.ReDeposited:
                    sStatusID = "7";
                    break;
                case ChequeStatus.ReturnedToSender:
                    sStatusID = "8";
                    break;
                case ChequeStatus.Deleted:
                    sStatusID = "9";
                    break;
                case ChequeStatus.Reserved_For_Factoring:
                    sStatusID = "20";
                    break;
                case ChequeStatus.Factored:
                    sStatusID = "21";
                    break;
                case ChequeStatus.Factoring_Deposited:
                    sStatusID = "22";
                    break;
                case ChequeStatus.Default:
                    sStatusID = "default";
                    break;

            }
            return sStatusID;
        }
