        #region Get Auto Generated GLCode
        public static string getAutoGeneratedGLCode(string AddCodes, string CodeID)
        {
            string sCode = "";
            tbl_securityConfigForms detail = tbl_securityConfigForms.Select(CodeID);
            if (detail != null & detail.Counter < 10)
            {
                sCode = Convert.ToString(detail.Counter);
                sCode += AddCodes;
                detail.Counter++;
                detail.Update();
            }
            return sCode;
        }
