        #region Get Output UOM_ID from SectionID
        public static string getUOMID_FromSectionID(string sSectionID)
        {
            string sUOMCode = "";
            switch (sSectionID)
            {
                case "SEC/001": sUOMCode = "kg"; break; //extrusion
                case "SEC/002": sUOMCode = "m"; break; //Lamination
                case "SEC/003": sUOMCode = "m"; break; //Slitting
                case "SEC/004": sUOMCode = "m"; break; //flexo
                case "SEC/005": sUOMCode = "NOS"; break; //Cutting 
                case "SEC/006": sUOMCode = "NOS"; break; //Pouch 
                // case "SEC/007": sUOMCode = "Kg"; break;
                case "SEC/0008": sUOMCode = "m"; break; //Graviour
                case "SEC/0010": sUOMCode = "NOS"; break; //Shrink 
                case "SEC/0012": sUOMCode = "m"; break; //Inspection
            }
            return sUOMCode;
        }
        #endregion
    }
